# Surah Saba (chapter 34) — part 4: ayat 31-40 (IDs 3637-3646)
SURAH = 34

ENTRIES = {
3637: (
"اور جنہوں نے کفر کیا وہ کہتے ہیں — ہم اس قرآن پر ایمان نہیں لائیں گے اور نہ اس پر جو اس سے پہلے ہے — اور کاش تم دیکھو جب ظالم اپنے رب کے سامنے کھڑے ہوں — ان کا ایک دوسرے سے بات کرنا — کمزور لوگ تکبر کرنے والوں سے کہیں گے — اگر تم نہ ہوتے تو ہم ایمان لے آتے",
"""۱۔ منکرینِ قرآن — واثیر؛ الظلمون؛ کمزور و مستکبرین کا جھگڑا۔
۲۔ ’’وَقَالَ الَّذِينَ كَفَرُوا لَن نُّؤْمِنَ بِهَٰذَا الْقُرْآنِ وَلَا بِالَّذِي بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰ إِذِ الظَّالِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ الْقَوْلَ يَقُولُ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا لَوْلَا أَنتُمْ لَكُنَّا مُؤْمِنِينَ‘‘ — اور جنہوں نے کفر کیا وہ کہتے ہیں — ہم اس قرآن پر ایمان نہیں لائیں گے اور نہ اس پر جو اس سے پہلے ہے — اور کاش تم دیکھو جب ظالم اپنے رب کے سامنے کھڑے ہوں — ان کا ایک دوسرے سے بات کرنا — کمزور لوگ تکبر کرنے والوں سے کہیں گے — اگر تم نہ ہوتے تو ہم ایمان لے آتے — یعنی اور جنہوں نے کفر کیا وہ کہتے ہیں ہم اس قرآن پر ایمان نہیں لائیں گے اور نہ اس پر جو اس سے پہلے ہے اور کاش تم دیکھو جب ظالم اپنے رب کے سامنے کھڑے ہوں ان کا ایک دوسرے سے بات کرنا کمزور لوگ تکبر کرنے والوں سے کہیں گے اگر تم نہ ہوتے تو ہم ایمان لے آتے۔
۳۔ عملی سبق: قرآن پر ایمان لاؤ؛ تکبر چھوڑو؛ اللہ سے ڈرو۔"""
),
3638: (
"تکبر کرنے والے کمزور لوگوں سے کہیں گے — کیا ہم نے تمہیں ہدایت سے روکا اس کے بعد کہ وہ تمہارے پاس آ چکی — بلکہ تم خود مجرم تھے",
"""۱۔ مستکبرین کا جواب — الزام؛ جرم۔
۲۔ ’’قَالَ الَّذِينَ اسْتَكْبَرُوا لِلَّذِينَ اسْتُضْعِفُوا أَنَحْنُ صَدَدْنَاكُمْ عَنِ الْهُدَىٰ بَعْدَ إِذْ جَاءَكُم بَلْ كُنتُم مُّجْرِمِينَ‘‘ — تکبر کرنے والے کمزور لوگوں سے کہیں گے — کیا ہم نے تمہیں ہدایت سے روکا اس کے بعد کہ وہ تمہارے پاس آ چکی — بلکہ تم خود مجرم تھے — یعنی تکبر کرنے والے کمزور لوگوں سے کہیں گے کیا ہم نے تمہیں ہدایت سے روکا اس کے بعد کہ وہ تمہارے پاس آ چکی بلکہ تم خود مجرم تھے۔
۳۔ عملی سبق: اپنی غلطی قبول کرو؛ دوسروں پر الزام نہ دو؛ اللہ سے ڈرو۔"""
),
3639: (
"اور کمزور لوگ تکبر کرنے والوں سے کہیں گے — بلکہ رات دن کی چال تھی جب تم ہمیں حکم دیتے تھے کہ ہم اللہ سے کفر کریں اور اس کے ساتھ شریک بنائیں — اور انہوں نے ندامت چھپائی جب انہوں نے عذاب دیکھا — اور ہم نے کافروں کی گردنوں میں طوق ڈال دیے — انہیں صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے",
"""۱۔ کمزوروں کا جواب — مكر الليل و النهار؛ ندامت؛ طوق؛ اعمال کا بدلہ۔
۲۔ ’’وَقَالَ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا بَلْ مَكْرُ اللَّيْلِ وَالنَّهَارِ إِذْ تَأْمُرُونَنَا أَن نَّكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُ أَندَادًا وَأَسَرُّوا النَّدَامَۃَ لَمَّا رَأَوُا الْعَذَابَ وَجَعَلْنَا الْأَغْلَالَ فِي أَعْنَاقِ الَّذِينَ كَفَرُوا هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ‘‘ — اور کمزور لوگ تکبر کرنے والوں سے کہیں گے — بلکہ رات دن کی چال تھی جب تم ہمیں حکم دیتے تھے کہ ہم اللہ سے کفر کریں اور اس کے ساتھ شریک بنائیں — اور انہوں نے ندامت چھپائی جب انہوں نے عذاب دیکھا — اور ہم نے کافروں کی گردنوں میں طوق ڈال دیے — انہیں صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے — یعنی اور کمزور لوگ تکبر کرنے والوں سے کہیں گے بلکہ رات دن کی چال تھی جب تم ہمیں حکم دیتے تھے کہ ہم اللہ سے کفر کریں اور اس کے ساتھ شریک بنائیں اور انہوں نے ندامت چھپائی جب انہوں نے عذاب دیکھا اور ہم نے کافروں کی گردنوں میں طوق ڈال دیے انہیں صرف وہی بدلہ دیا جائے گا جو وہ کرتے تھے۔
۳۔ عملی سبق: کفر و شرک سے بچو؛ اپنے اعمال درست کرو؛ اللہ سے ڈرو۔"""
),
3640: (
"اور ہم نے جب بھی کسی بستی میں کوئی ڈرانے والا بھیجا اس کے آسودہ حال لوگوں نے کہا — ہم اس بات پر ایمان نہیں رکھتے جو تمہارے ساتھ بھیجی گئی ہے",
"""۱۔ سابقہ اقوام — مترفو (آسودہ حال لوگ)؛ عدمِ ایمان۔
۲۔ ’’وَمَا أَرْسَلْنَا فِي قَرْيَۃٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا بِمَا أُرْسِلْتُم بِهِ كَافِرُونَ‘‘ — اور ہم نے جب بھی کسی بستی میں کوئی ڈرانے والا بھیجا اس کے آسودہ حال لوگوں نے کہا — ہم اس بات پر ایمان نہیں رکھتے جو تمہارے ساتھ بھیجی گئی ہے — یعنی اور ہم نے جب بھی کسی بستی میں کوئی ڈرانے والا بھیجا اس کے آسودہ حال لوگوں نے کہا ہم اس بات پر ایمان نہیں رکھتے جو تمہارے ساتھ بھیجی گئی ہے۔
۳۔ عملی سبق: دولت اور آسودگی کے بے شکریں نہ بنو؛ حق کو قبول کرو؛ اللہ سے ڈرو۔"""
),
3641: (
"اور انہوں نے کہا ہم زیادہ مال اور اولاد رکھتے ہیں — اور ہم عذاب نہیں ہوں گے",
"""۱۔ آسودہ حال لوگ — مال و اولاد؛ عدمِ عذاب کا گمان۔
۲۔ ’’وَقَالُوا نَحْنُ أَكْثَرُ أَمْوَالًا وَأَوْلَادًا وَمَا نَحْنُ بِمُعَذَّبِينَ‘‘ — اور انہوں نے کہا ہم زیادہ مال اور اولاد رکھتے ہیں — اور ہم عذاب نہیں ہوں گے — یعنی اور انہوں نے کہا ہم زیادہ مال اور اولاد رکھتے ہیں اور ہم عذاب نہیں ہوں گے۔
۳۔ عملی سبق: مال و اولاد اللہ کی آزمائش ہے؛ تکبر نہ کرو؛ اللہ سے ڈرو۔"""
),
3642: (
"کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اور جس کے لیے چاہے تنگی کرتا ہے — لیکن اکثر لوگ جانتے نہیں",
"""۱۔ رزق کی تقسیم — اللہ کا اختیار؛ اکثر جاہل۔
۲۔ ’’قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ‘‘ — کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اور جس کے لیے چاہے تنگی کرتا ہے — لیکن اکثر لوگ جانتے نہیں — یعنی کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اور جس کے لیے چاہے تنگی کرتا ہے لیکن اکثر لوگ جانتے نہیں۔
۳۔ عملی سبق: رزق میں کمی بیشی اللہ کا فیصلہ ہے؛ راضی رہو؛ اللہ سے ڈرو۔"""
),
3643: (
"اور تمہارے اموال اور تمہاری اولاد وہ نہیں جو تمہیں ہمارے ہاں نزدیکی کا درجہ دیں — سوائے یہ کہ کوئی ایمان لائے اور نیک عمل کرے — تو ان کے لیے ان کے اعمال کے بدلے دوہرا بدلہ ہے — اور وہ محلوں میں امن سے ہوں گے",
"""۱۔ مال و اولاد کی حقیقتیں — قُربِ الٰہی؛ ایمان و عمل؛ دوہرا اجر؛ محلوں میں امن۔
۲۔ ’’وَمَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُم بِالَّتِي تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰ إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَأُولَٰئِكَ لَهُمْ جَزَاءُ الضِّعْفِ بِمَا عَمِلُوا وَهُمْ فِي الْغُرُفَاتِ آمِنُونَ‘‘ — اور تمہارے اموال اور تمہاری اولاد وہ نہیں جو تمہیں ہمارے ہاں نزدیکی کا درجہ دیں — سوائے یہ کہ کوئی ایمان لائے اور نیک عمل کرے — تو ان کے لیے ان کے اعمال کے بدلے دوہرا بدلہ ہے — اور وہ محلوں میں امن سے ہوں گے — یعنی اور تمہارے اموال اور تمہاری اولاد وہ نہیں جو تمہیں ہمارے ہاں نزدیکی کا درجہ دیں سوائے یہ کہ کوئی ایمان لائے اور نیک عمل کرے تو ان کے لیے ان کے اعمال کے بدلے دوہرا بدلہ ہے اور وہ محلوں میں امن سے ہوں گے۔
۳۔ عملی سبق: ایمان و عمل پر بھروسہ رکھو؛ مال پر ناز نہ کرو؛ اللہ سے ڈرو۔"""
),
3644: (
"اور جو ہماری آیات میں محنت کرتے ہوں کہ ہمیں عاجز کر دیں وہ عذاب میں حاضر کیے جائیں گے",
"""۱۔ معاجزین — عذاب میں حاضر۔
۲۔ ’’وَالَّذِينَ يَسْعَوْنَ فِي آيَاتِنَا مُعَاجِزِينَ أُولَٰئِكَ فِي الْعَذَابِ مُحْضَرُونَ‘‘ —اور جو ہماری آیات میں محنت کرتے ہوں کہ ہمیں عاجز کر دیں وہ عذاب میں حاضر کیے جائیں گے۔
۳۔ عملی سبق: اللہ کی آیات سے مذاق نہ کرو؛ اللہ سے ڈرو؛ ایمان لاؤ۔"""
),
3645: (
"کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اپنے بندوں میں سے اور جس کے لیے چاہے تنگی کرتا ہے — اور تم جو چیز بھی خرچ کرو وہ اس کا عوض دیتا ہے — اور وہ بہترین رزق دینے والا ہے",
"""۱۔ رزق — اللہ کا؛ انفاق کا عوض؛ بہترین رازق۔
۲۔ ’’قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ وَمَا أَنفَقْتُم مِّن شَيْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ‘‘ — کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اپنے بندوں میں سے اور جس کے لیے چاہے تنگی کرتا ہے — اور تم جو چیز بھی خرچ کرو وہ اس کا عوض دیتا ہے — اور وہ بہترین رزق دینے والا ہے — یعنی کہہ دیجیے بے شک میرا رب جس کے لیے چاہے رزق وسیع کرتا ہے اپنے بندوں میں سے اور جس کے لیے چاہے تنگی کرتا ہے اور تم جو چیز بھی خرچ کرو وہ اس کا عوض دیتا ہے اور وہ بہترین رزق دینے والا ہے۔
۳۔ عملی سبق: اللہ کے راستے میں خرچ کرو؛ یقین رکھو کہ وہ بدلہ دیتا ہے؛ اللہ سے ڈرو۔"""
),
3646: (
"اور جس دن ان سب کو جمع کرے گا پھر فرشتوں سے کہے گا — کیا یہی تمہاری عبادت کرتے تھے",
"""۱۔ قیامت — سب کا جمع؛ فرشتوں سے دریافت۔
۲۔ ’’وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَائِكَۃِ أَهَٰؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ‘‘ — اور جس دن ان سب کو جمع کرے گا پھر فرشتوں سے کہے گا — کیا یہی تمہاری عبادت کرتے تھے — یعنی اور جس دن ان سب کو جمع کرے گا پھر فرشتوں سے کہے گا کیا یہی تمہاری عبادت کرتے تھے۔
۳۔ عملی سبق: عبادت صرف اللہ کی کرو؛ شرک سے بچو؛ اللہ سے ڈرو۔"""
),
}
